window.kbPageData["views/entry/k-207b65184384ec4a"] = {"key":"entry/k-207b65184384ec4a","state":{"route":"entry/k-207b65184384ec4a"},"node":{"id":"k-207b65184384ec4a","mode":"k","title":"椭圆的短半轴与长轴","type":"概念与词义","domain":"数学","reading":"","intro":"","priority":100,"aliases":["椭圆的短半轴与长轴的几何意义","椭圆的最短中心距为短半轴，两点最大距离为长轴长"],"qs":["江苏 2023 A类 行测#55","江苏 2023 B类 行测#55"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"椭圆边界上的点到中心的最小距离等于短半轴长。边界两点间的最大距离等于长轴全长，即长半轴长的两倍。","review":{"definition":"椭圆边界上的点到中心的最小距离等于短半轴长。边界两点间的最大距离等于长轴全长，即长半轴长的两倍。","explanation":"短轴端点离中心最近，长轴端点离中心最远。任意两个边界点的距离至多是它们各自到中心的距离之和，长轴两端恰好达到这个上限。因此本题的短半轴为20米，长半轴为80÷2＝40米。","references":[],"evidence":"边界椭圆上一点到中心距离的最小值是20米，两点间距离的最大值为80米。","disposition":"独立词条","basis":"据原题和解析编释。","title":"椭圆的短半轴与长轴","related":[],"examFocus":{"江苏 2023 A类 行测#55":"辨认题给的两种距离各对应椭圆的哪个轴长，再考虑椭圆内正方形的面积上限。"}},"readings":[{"origin":"k-207b65184384ec4a","title":"椭圆的短半轴与长轴","qs":["江苏 2023 A类 行测#55"],"definition":"椭圆边界上的点到中心的最小距离等于短半轴长。边界两点间的最大距离等于长轴全长，即长半轴长的两倍。","explanation":"短轴端点离中心最近，长轴端点离中心最远。任意两个边界点的距离至多是它们各自到中心的距离之和，长轴两端恰好达到这个上限。因此本题的短半轴为20米，长半轴为80÷2＝40米。","evidence":"边界椭圆上一点到中心距离的最小值是20米，两点间距离的最大值为80米。","doubt":"","references":[]},{"origin":"k-b9349d7e5e1999e9","title":"椭圆的短半轴与长轴","qs":["江苏 2023 B类 行测#55"],"definition":"椭圆边界到中心的最小距离是短半轴长。椭圆上两点间的最大距离是长轴长，等于长半轴长的两倍。","explanation":"椭圆边界上的点到中心的距离介于短半轴长和长半轴长之间。由三角不等式，两点距离最多是长半轴长的两倍，长轴两端正好达到该上限。因此题中的20米直接给出短半轴，80米给出长轴，长半轴为40米。","evidence":"边界椭圆上一点到中心距离的最小值是20米，两点间距离的最大值为80米","doubt":"","references":[]}]},"questions":{"江苏 2023 A类 行测#55":{"paper":"江苏 2023 A类 行测","n":55,"mod":"数量关系","src":["22304fe4c340e19d7902.pdf",10],"asrc":["be17f9afe070cf13a0fb.pdf",16],"card":"9970ba0be856b879a69dc87e","links":[{"id":"k-207b65184384ec4a","role":"解题依据","why":"最近距离等于短半轴，边界两点的最远距离等于长轴全长。"}]},"江苏 2023 B类 行测#55":{"paper":"江苏 2023 B类 行测","n":55,"mod":"数量关系","src":["22262c34d18cd68fbee4.pdf",9],"asrc":["b08f2713d73015eac675.pdf",17],"card":"402b5b19ba26df84af04dd68","links":[{"id":"k-207b65184384ec4a","role":"解题依据","why":"两个距离条件分别确定短半轴和长半轴。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-207b65184384ec4a":[["江苏 2023 A类 行测#55","江苏 2023 B类 行测#55"]]}};
